import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"高级AI Core编程模型","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/advanced_ai_core_programming_model"},{"text":"SIMD与SIMT混合编程","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview"},{"text":"编程示例","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/programming_examples"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/programming_examples.md","filePath":"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/programming_examples.md","outlineHeaders":[{"level":2,"title":"场景说明","slug":"场景说明","link":"#场景说明"},{"level":2,"title":"定义SIMT VF函数","slug":"定义SIMT-VF函数","link":"#定义SIMT-VF函数"},{"level":2,"title":"调用VF函数","slug":"调用VF函数","link":"#调用VF函数"},{"level":2,"title":"配置核函数（Kernel）启动","slug":"配置核函数（Kernel）启动","link":"#配置核函数（Kernel）启动"},{"level":2,"title":"数据同步","slug":"数据同步","link":"#数据同步"},{"level":2,"title":"结果说明","slug":"结果说明","link":"#结果说明"}],"lastUpdated":1787050286000}'),l={name:"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/programming_examples.md"};function t(e,s,d,o,_,i){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>编程示例<span id="ZH-CN_TOPIC_0000002563469531"></span></h1><p>本节以<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/05_simd_simt_hybrid/00_introduction/simd_simt_gather_and_adds">gather &amp; adds混合编程样例</a>为例，展示SIMD与SIMT混合编程的关键语法。</p><h2 id="场景说明">场景说明<span id="zh-cn_topic_0000002563469531_section164411381518"></span><a class="header-anchor" href="#场景说明">​</a></h2><p>样例从长度为100000的一维输入<code>input</code>中，按照<code>index</code>数组指定的位置离散读取8192个元素，并对读取结果执行加1操作：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">output</span><span class="p">[</span><span class="n">i</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">index</span><span class="p">[</span><span class="n">i</span><span class="p">]]</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span>
</code></pre></div><p>其中，离散读取<code>input[index[i]]</code>适合使用SIMT线程并行完成；加1操作面向连续Unified Buffer（UB）数据，适合使用SIMD向量计算完成。</p><table><thead><tr><th>数据</th><th>Shape</th><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>input</td><td>[100000]</td><td>float</td><td>被离散读取的输入数据</td></tr><tr><td>index</td><td>[8192]</td><td>uint32_t</td><td>每个输出元素对应的input下标</td></tr><tr><td>output</td><td>[8192]</td><td>float</td><td>gather后加1的输出结果</td></tr></tbody></table><p>样例启动8个Vector Core，每个Vector Core处理1024个输出元素。每个核内通过<code>asc_vf_call</code>启动一个SIMT VF函数，<code>dim3(THREAD_COUNT)</code>配置1024个SIMT线程，每个线程负责一个<code>index</code>元素。</p><h2 id="定义SIMT-VF函数">定义SIMT VF函数<span id="zh-cn_topic_0000002563469531_section1998615411431"></span><a class="header-anchor" href="#定义SIMT-VF函数">​</a></h2><p>SIMT VF函数使用<code>__simt_vf__</code>修饰，函数内可以使用<code>blockIdx</code>、<code>blockDim</code>、<code>threadIdx</code>等SIMT内置变量。下面代码中，每个线程根据自己的<code>threadIdx.x</code>读取一个<code>index</code>，再从GM输入<code>input</code>中读取对应数据并写入UB缓存<code>local_output</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">THREAD_COUNT</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1024</span><span class="p">;</span>

<span class="n">__simt_vf__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREAD_COUNT</span><span class="p">)</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">simt_gather</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">local_output</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">output_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">output_total_length</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">idx</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">gather_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">index</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">gather_idx</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="n">local_output</span><span class="p">[</span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">gather_idx</span><span class="p">];</span>
<span class="p">}</span>
</code></pre></div><p>关键点如下：</p><ul><li><code>__simt_vf__</code>标识该函数在SIMT单元执行。</li><li><code>__launch_bounds__(THREAD_COUNT)</code>声明该SIMT VF函数的最大线程数。</li><li><code>__gm__</code>用于标识GM指针，<code>__ubuf__</code>用于标识UB指针。</li><li><code>threadIdx.x</code>表示当前线程在线程块内的索引，用于让不同线程处理不同元素。</li></ul><h2 id="调用VF函数">调用VF函数<span id="zh-cn_topic_0000002563469531_section199351451451"></span><a class="header-anchor" href="#调用VF函数">​</a></h2><p>在<code>__global__ __vector__</code>核函数（Kernel）中，申请UB空间作为共享内存，再通过<code>asc_vf_call&lt;simt_gather&gt;</code>调用SIMT VF函数完成gather计算，而后通过<code>asc_vf_call&lt;simd_adds&gt;</code>调用SIMD VF函数执行后续的加法计算。在调用SIMT VF函数时，<code>asc_vf_call</code>的第一个参数<code>dim3(THREAD_COUNT)</code>表示本次SIMT VF调用启动1024个线程。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_and_adds_kernel</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length_per_block</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">index_total_length</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">block_num</span><span class="p">;</span>
<span class="w">    </span><span class="k">extern</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">local_output</span><span class="p">[];</span>

<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">simt_gather</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">        </span><span class="n">dim3</span><span class="p">(</span><span class="n">THREAD_COUNT</span><span class="p">),</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="n">local_output</span><span class="p">,</span>
<span class="w">        </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length_per_block</span><span class="p">);</span>

<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_get_vf_len</span><span class="p">()</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_times</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">index_total_length_per_block</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// 启动SIMD VF函数，对Gather结果执行加1操作。</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">simd_adds</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">        </span><span class="n">local_output</span><span class="p">,</span><span class="w"> </span><span class="n">local_output</span><span class="p">,</span>
<span class="w">        </span><span class="n">index_total_length_per_block</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p><code>asc_vf_call&lt;simt_gather&gt;</code>调用后，当前Vector Core内会启动一个SIMT线程块。以本样例为例，<code>index_total_length_per_block</code>为1024，<code>THREAD_COUNT</code>也为1024，因此一个线程块即可处理当前核负责的全部输出元素。</p><h2 id="配置核函数（Kernel）启动">配置核函数（Kernel）启动<span id="zh-cn_topic_0000002563469531_section1680714261755"></span><a class="header-anchor" href="#配置核函数（Kernel）启动">​</a></h2><p>Host侧通过<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>内核调用符启动<code>__global__ __vector__</code>核函数（Kernel）。下面代码中，<code>num_blocks</code>表示启动8个Vector Core，<code>dyn_ub_size</code>表示动态UB大小，本样例取值为<code>THREAD_COUNT * sizeof(float)</code>，<code>stream</code>用于维护异步执行顺序。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">100000</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">num_blocks</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dyn_ub_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">THREAD_COUNT</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>

<span class="n">gather_and_adds_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="n">num_blocks</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ub_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">);</span>
</code></pre></div><p><code>&lt;&lt;&lt;&gt;&gt;&gt;</code>中的三个配置参数含义如下：</p><table><thead><tr><th>参数</th><th>本样例取值</th><th>说明</th></tr></thead><tbody><tr><td>num_blocks</td><td>8</td><td>启动8个Vector Core，每个核处理1024个输出元素</td></tr><tr><td>dyn_ub_size</td><td>THREAD_COUNT * sizeof(float)</td><td>为核函数（Kernel）配置动态UB空间</td></tr><tr><td>stream</td><td>stream</td><td>指定ACL运行时流</td></tr></tbody></table><h2 id="数据同步">数据同步<span id="zh-cn_topic_0000002563469531_section_data_sync"></span><a class="header-anchor" href="#数据同步">​</a></h2><p>SIMT VF和SIMD VF属于Vector流水，与MTE数据搬运异步执行，因此需要确保数据搬运操作与VF函数调用之间正确同步。本例中，SIMT VF函数直接读取GM输入数据，不涉及数据搬入；SIMD VF执行完后，需要将数据从UB写出到GM，此时需要加上同步指令保证操作顺序。整体流程如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">simt_gather</span><span class="o">&gt;</span><span class="p">(...);</span>
<span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">simd_adds</span><span class="o">&gt;</span><span class="p">(...);</span>
<span class="c1">// 同步Vector计算流水和MTE3搬出流水，确保Adds结果写入UB后再搬运到GM。</span>
<span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">asc_copy_ub2gm_align</span><span class="p">(...);</span>
</code></pre></div><h2 id="结果说明">结果说明<span id="zh-cn_topic_0000002563469531_section1184165711616"></span><a class="header-anchor" href="#结果说明">​</a></h2><p>样例执行后会生成<code>output/output.bin</code>，输出中第<code>i</code>个元素满足：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">output</span><span class="p">[</span><span class="n">i</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">index</span><span class="p">[</span><span class="n">i</span><span class="p">]]</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span>
</code></pre></div><p>完整工程包含输入生成脚本和结果校验脚本，执行精度校验通过时输出如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>test pass!
</code></pre></div></article></div>`,1)])])}const g=a(l,[["render",t]]);export{h as __pageData,g as default};
